import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String[] args) throws Exception
    {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output=new StringBuilder();
        String[] line1=br.readLine().split(" ");
        int n=Integer.parseInt(line1[0]);
        int b=Integer.parseInt(line1[1]);
        int[] array=new int[n];
        int[] prefixSum=new int[n];
        String[] line2=br.readLine().split(" ");
        for(int i=0;i<n;i++)
        {
            array[i]=Integer.parseInt(line2[i]);
        }
        int balanceCount=0;
        for(int i=0;i<n;i++)
        {
            if(array[i]%2==0) balanceCount++;
            else balanceCount--;
            prefixSum[i]=balanceCount;
        }
        List<Integer> diffList=new ArrayList<>();
        for(int i=0;i<n-1;i++)
        {
            if(prefixSum[i]==0)
                diffList.add(Math.abs(array[i]-array[i+1]));
        }
        Collections.sort(diffList);
        int totalCuts=0, accumulated=0;
        for(int diff:diffList)
        {
            if(accumulated+diff<=b){accumulated+=diff; totalCuts++;}
            if(accumulated>=b) break;
        }
        System.out.print(totalCuts);
    }
}
